import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    x = int(data[1])

    a = []
    idx = 2
    for _ in range(n):
        a.append(int(data[idx]))
        idx += 1

    min_val = min(a)

    k = 0
    if min_val > 0:
        k = (a[x-1] - 1) // n
    else:
        k = 0

    if k < min_val:
        k = min_val

    result = []
    for val in a:
        if val - k >= 0:
            result.append(val - k)
        else:
            result.append(val + (n - k))

    print(' '.join(map(str, result)))

if __name__ == '__main__':
    solve()
